pub(super) fn tables(version: UnicodeDataVersion) -> Tables {
    match version {
        UnicodeDataVersion::V13_0 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_0,
            full: FULL_0,
            cased: CASED_0,
            ignorable: IGNORABLE_0,
        },
        UnicodeDataVersion::V14_0 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_1,
            full: FULL_0,
            cased: CASED_1,
            ignorable: IGNORABLE_1,
        },
        UnicodeDataVersion::V15_0 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_1,
            full: FULL_0,
            cased: CASED_2,
            ignorable: IGNORABLE_2,
        },
        UnicodeDataVersion::V15_1 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_1,
            full: FULL_0,
            cased: CASED_2,
            ignorable: IGNORABLE_2,
        },
        UnicodeDataVersion::V16_0 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_2,
            full: FULL_0,
            cased: CASED_3,
            ignorable: IGNORABLE_3,
        },
        UnicodeDataVersion::V17_0 => Tables {
            simple: SIMPLE,
            overrides: OVERRIDES_3,
            full: FULL_0,
            cased: CASED_4,
            ignorable: IGNORABLE_4,
        },
    }
}
